package org.freecad.mobilelab;
import org.json.*;import java.io.*;import java.nio.file.*;import java.util.*;
public final class RenderingRegression {
 static int checks;interface Action{void run()throws Exception;}static void check(boolean b,String s){if(!b)throw new AssertionError(s);checks++;}static void near(double a,double b){check(Math.abs(a-b)<1e-5,"wrong value");}static void reject(Action a)throws Exception{try{a.run();}catch(Exception e){checks++;return;}throw new AssertionError("Invalid render setting accepted");}
 static JSONObject obj(int id)throws Exception{JSONArray a=new JSONArray(NativeCad.objects());for(int i=0;i<a.length();i++)if(a.getJSONObject(i).getInt("id")==id)return a.getJSONObject(i);throw new AssertionError("missing");}
 static int opaque(SoftwareRasterizer.Image i){int n=0;for(int p:i.pixels)if(p>>>24!=0)n++;return n;}
 public static void main(String[] args)throws Exception{NativeCad.clear();ProjectStore.reset();int ring=NativeCad.create("Ring",new double[]{18,1.6,3});NativeCad.surfaceMaterial(ring,new double[]{.25,.85});float[] vertices=NativeCad.meshAtDetail(ring,50000),materials=NativeCad.surfaceValues();check(materials.length==vertices.length/5,"Material and geometry buffers disagree");for(int i=0;i<materials.length;i+=2){near(materials[i],.25);near(materials[i+1],.85);}MeshFrame mesh=new MeshFrame(vertices,NativeCad.lines(ring),materials);check(mesh.wireBuffer().capacity()==vertices.length*2,"Wireframe buffer bounds");int[] checksums=new int[4];for(int style=0;style<4;style++){SoftwareRasterizer.Image image=SoftwareRasterizer.render(mesh,320,320,-32,-58,1,0,0,false,new RenderSettings(style,false,0,true));check(opaque(image)>100,"Rendering mode empty: "+style);check(image.pixels[0]==0,"Transparent background missing");checksums[style]=Arrays.hashCode(image.pixels);if(style==RenderSettings.ZEBRA){Set<Integer> colors=new HashSet<>();for(int p:image.pixels)if(p>>>24!=0)colors.add(p);check(colors.size()==2,"Zebra did not produce crisp stripes");}}for(int i=0;i<checksums.length;i++)for(int j=0;j<i;j++)check(checksums[i]!=checksums[j],"Display modes are indistinguishable");SoftwareRasterizer.Image hidden=SoftwareRasterizer.render(mesh,320,320,-32,-58,1,0,0,false,new RenderSettings(0,true,-100,true));check(opaque(hidden)==0,"Clipping did not hide geometry");SoftwareRasterizer.Image partial=SoftwareRasterizer.render(mesh,320,320,-32,-58,1,0,0,false,new RenderSettings(0,true,1.5,true));check(opaque(partial)>0&&opaque(partial)<opaque(SoftwareRasterizer.render(mesh,320,320,-32,-58,1,0,0,false,new RenderSettings(0,false,0,true))),"Clipping did not cut pixels through triangles");SoftwareRasterizer.Image large=SoftwareRasterizer.render(mesh,2048,2048,-32,-58,1,0,0,false,new RenderSettings(1,false,0,true));check(large.pixels.length==4194304&&opaque(large)>10000,"High resolution export empty");
  for(double rough:new double[]{.04,.2,1})for(double metal:new double[]{0,.5,1})for(double z:new double[]{-1,0,1}){float[] c=StudioLighting.color(0,0,1,1,1,z,new float[]{.9f,.6f,.2f},rough,metal);for(float v:c)check(Float.isFinite(v)&&v>=0&&v<=1,"PBR math out of range");}reject(()->new MeshFrame(vertices,new float[0],new float[1]));reject(()->NativeCad.surfaceMaterial(ring,new double[]{0,1}));reject(()->SoftwareRasterizer.render(mesh,4096,4096,0,0,1,0,0));
  File root=Files.createTempDirectory("materials-").toFile(),cache=new File(root,"cache");cache.mkdir();try{File project=new File(root,"material.fcml");ProjectStore.save(project,cache);NativeCad.beginTransaction(true);try{int id=ProjectStore.restore(project,cache);NativeCad.commitTransaction();JSONArray m=obj(id).getJSONArray("surfaceMaterial");near(m.getDouble(0),.25);near(m.getDouble(1),.85);}catch(Throwable x){NativeCad.rollbackTransaction();throw x;}}finally{ArchiveIO.deleteTree(root);}System.out.println("PASS: "+checks+" rendering assertions: material buffer alignment, persisted roughness/metallic, distinct shaded/studio/zebra/wireframe modes, partial pixel clipping, transparent 2048 output and finite bounded PBR math");
 }
}
